param($appid, $org, $id, $Thumb, $h, $guid, $x, $b)

Get-AGMImage -filtervalue appid=$appid
Connect-SPOService -Url https://$org-admin.example.com
Get-AGMAPIData -endpoint /diskpool/$id/vault
Get-ChildItem -Path Cert:\LocalMachine\My\$Thumb
Remove-Item \\$h\$Script:Path\*.kirbi
auditpol /get /subcategory:"$guid"
auditpol /set /subcategory:'Logon' /failure:enable
Write-Output x$ x$- x`$a a"$b""c" a'$b''c' a=b>c

switch ($x) {
    "1" { Write-Output 'one' }
    '2' { Write-Output 'two' }
    "a$b" { Write-Output 'interpolated' }
    "^365Group$" { Write-Output 'anchored' }
    abc { Write-Output 'bare' }
}

# ERROR:
switch ($group) {
    "Admins" { Write-Output 'group' }
}
# ERROR:
switch ($group) {
    Admins { Write-Output 'group' }
}

switch ($group) {
    "Admin" { Write-Output 'group' }
}
switch ($group) {
    'Users' { Write-Output 'group' }
}
